int knapsack(int n, int W, int w[], int v[], int c[]) {
    int dp[201] = {0};
    int next[201];
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= W; ++j) {
            next[j] = dp[j];
            for (int t = 1; t <= w[i] && t <= j; ++t) {
                int gain = v[i] - (w[i] - t) * c[i];
                int candidate = dp[j - t] + gain;
                if (candidate > next[j]) next[j] = candidate;
            }
        }
        for (int j = 0; j <= W; ++j) dp[j] = next[j];
    }
    return dp[W];
}

